import os
import sys
from typing import Dict, List, Tuple

import openpyxl
from openpyxl.utils import get_column_letter

INPUT_PATH = "/root/data/workbook.xlsx"
OUTPUT_PATH = "/root/output/result.xlsx"


def fmt_row(ws, row: int, col_start: int, col_end: int) -> List:
    return [ws.cell(row=row, column=c).value for c in range(col_start, col_end + 1)]


def print_preliminary_inspection() -> None:
    wb = openpyxl.load_workbook(INPUT_PATH, data_only=False)

    print("## Preliminary inspection")
    print("Workbook:", INPUT_PATH)
    print("Sheet names:", wb.sheetnames)
    if "Task" not in wb.sheetnames or "Data" not in wb.sheetnames:
        raise RuntimeError("Expected sheets 'Task' and 'Data' to exist")

    ws_task = wb["Task"]
    ws_data = wb["Data"]

    # Task: row 10 year headers in H-L
    years = [ws_task[f"{c}10"].value for c in ["H", "I", "J", "K", "L"]]
    print("\nTask!H10:L10 year headers:", years)

    # Task: series codes in D rows 12-17, 19-24, 26-31
    print("\nTask series codes (column D)")
    blocks = [list(range(12, 18)), list(range(19, 25)), list(range(26, 32))]
    for block in blocks:
        print(f"  Rows {block[0]}-{block[-1]}:")
        for r in block:
            print(f"    D{r}: {ws_task[f'D{r}'].value}")

    # Task: layout rows 35-50
    print("\nTask rows 35-50 layout (A-L)")
    for r in range(35, 51):
        vals = fmt_row(ws_task, r, 1, 12)
        print(f"  Row {r}: {vals}")

    # Data: show header row 4 and data rows 21-38
    print("\nData header row 4 (A-N)")
    print("  Row 4:", fmt_row(ws_data, 4, 1, 14))

    print("\nData rows 21-38 (A-M)")
    for r in range(21, 39):
        vals = fmt_row(ws_data, r, 1, 13)
        print(f"  Row {r}: {vals}")

    # Find year header columns on Data row 4 that match Task years
    year_to_col: Dict[int, int] = {}
    for c in range(1, ws_data.max_column + 1):
        v = ws_data.cell(row=4, column=c).value
        if isinstance(v, int) and v in years:
            year_to_col[v] = c

    if year_to_col:
        cols = [(y, get_column_letter(c), c) for y, c in sorted(year_to_col.items())]
        print("\nData year header columns matching Task years (from row 4):")
        for y, col_letter, col_idx in cols:
            print(f"  {y}: {col_letter} (index {col_idx})")
    else:
        print("\nWARNING: Did not find matching year headers on Data row 4")

    wb.close()


def detect_data_layout(wb) -> Tuple[str, int, int, Dict[int, int]]:
    """Return (series_code_col_letter, header_row, data_start_row, year_to_col)."""
    ws_data = wb["Data"]

    header_row = 4
    data_start_row = 21
    data_end_row = 38

    # Detect the series-code column by looking for "Series code" in the header row.
    series_code_col = None
    for c in range(1, ws_data.max_column + 1):
        v = ws_data.cell(row=header_row, column=c).value
        if isinstance(v, str) and v.strip().lower() == "series code":
            series_code_col = c
            break

    if series_code_col is None:
        # Fallback: based on inspection, series codes appear in column D.
        series_code_col = 4

    # Task years are assumed to be in Task!H10:L10
    ws_task = wb["Task"]
    task_years = [ws_task[f"{c}10"].value for c in ["H", "I", "J", "K", "L"]]
    task_years_int = [int(y) for y in task_years if y is not None]

    year_to_col: Dict[int, int] = {}
    for c in range(1, ws_data.max_column + 1):
        v = ws_data.cell(row=header_row, column=c).value
        if isinstance(v, int) and v in task_years_int:
            year_to_col[v] = c

    missing = [y for y in task_years_int if y not in year_to_col]
    if missing:
        raise RuntimeError(
            f"Could not locate all Task years on Data header row {header_row}. Missing: {missing}."
        )

    return get_column_letter(series_code_col), header_row, data_start_row, year_to_col


def write_formulas() -> None:
    wb = openpyxl.load_workbook(INPUT_PATH, data_only=False)
    ws_task = wb["Task"]
    ws_data = wb["Data"]

    series_code_col_letter, data_header_row, data_start_row, year_to_col = detect_data_layout(wb)
    data_end_row = 38

    # Define the year columns span on Data (for INDEX and column MATCH arrays)
    year_cols_sorted = [year_to_col[y] for y in sorted(year_to_col.keys())]
    data_year_col_min = min(year_cols_sorted)
    data_year_col_max = max(year_cols_sorted)
    data_year_col_min_letter = get_column_letter(data_year_col_min)
    data_year_col_max_letter = get_column_letter(data_year_col_max)

    print("\n## Writing formulas")
    print(
        "Detected Data layout:"
        f" series_code_col={series_code_col_letter}, header_row={data_header_row},"
        f" data_rows={data_start_row}-{data_end_row}, year_cols={data_year_col_min_letter}-{data_year_col_max_letter}"
    )

    # Step 1: populate lookup formulas for three blocks on Task
    target_rows = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32))
    target_cols_letters = ["H", "I", "J", "K", "L"]

    index_range = f"Data!${data_year_col_min_letter}${data_start_row}:${data_year_col_max_letter}${data_end_row}"
    row_match_range = f"Data!${series_code_col_letter}${data_start_row}:${series_code_col_letter}${data_end_row}"
    col_match_range = f"Data!${data_year_col_min_letter}${data_header_row}:${data_year_col_max_letter}${data_header_row}"

    for r in target_rows:
        for col_letter in target_cols_letters:
            formula = (
                f"=INDEX({index_range},"
                f"MATCH($D{r},{row_match_range},0),"
                f"MATCH({col_letter}$10,{col_match_range},0))"
            )
            ws_task[f"{col_letter}{r}"].value = formula

    # Step 2: Net capacity headroom percentages in H35:L40
    # Map Task clusters by row offsets: rows 35-40 correspond to rows 12-17/19-24/26-31.
    for offset in range(0, 6):
        r_out = 35 + offset
        r_open = 12 + offset
        r_used = 19 + offset
        r_beds = 26 + offset
        for col_letter in target_cols_letters:
            ws_task[f"{col_letter}{r_out}"].value = (
                f"=({col_letter}{r_open}-{col_letter}{r_used})/{col_letter}{r_beds}*100"
            )

    # Step 2b: Summary statistics in H42:L47 (map by labels in column E)
    def stat_kind(label) -> Tuple[str, float]:
        if not isinstance(label, str):
            return ("", 0.0)
        l = label.strip().lower()
        if "minimum" in l:
            return ("MIN", 0.0)
        if "maximum" in l:
            return ("MAX", 0.0)
        if "median" in l:
            return ("MEDIAN", 0.0)
        if "simple mean" in l or l == "mean" or "average" in l:
            return ("AVERAGE", 0.0)
        if "25th" in l and "percentile" in l:
            return ("PERCENTILE", 0.25)
        if "75th" in l and "percentile" in l:
            return ("PERCENTILE", 0.75)
        return ("", 0.0)

    for r in range(42, 48):
        label = ws_task[f"E{r}"].value
        func, p = stat_kind(label)
        if not func:
            raise RuntimeError(f"Could not map statistic label in Task!E{r}: {label!r}")

        for col_letter in target_cols_letters:
            rng = f"{col_letter}35:{col_letter}40"
            if func == "PERCENTILE":
                ws_task[f"{col_letter}{r}"].value = f"=PERCENTILE({rng},{p})"
            else:
                ws_task[f"{col_letter}{r}"].value = f"={func}({rng})"

    # Step 3: Weighted mean in H50:L50
    for col_letter in target_cols_letters:
        ws_task[f"{col_letter}50"].value = (
            f"=SUMPRODUCT({col_letter}35:{col_letter}40,{col_letter}26:{col_letter}31)"
            f"/SUM({col_letter}26:{col_letter}31)"
        )

    # Save
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    wb.save(OUTPUT_PATH)
    wb.close()


def verify_output_sample() -> None:
    wb = openpyxl.load_workbook(OUTPUT_PATH, data_only=False)
    ws = wb["Task"]

    print("\n## Verification sample (formulas as saved)")
    for addr in ["H12", "I12", "H35", "I35", "H42", "I42", "H50", "I50"]:
        print(f"Task!{addr}: {ws[addr].value}")

    wb.close()


def main() -> None:
    print_preliminary_inspection()
    # Re-open and edit
    write_formulas()
    verify_output_sample()
    print("\nWrote:", OUTPUT_PATH)


if __name__ == "__main__":
    main()

